insert into public.catalogue_master_products(category_id,branch_id,manufacturer_id,model,package_key,package_name,catalogue_category,main_category,product_type,notes,active,customer_visible)
select c.id,b.id,m.id,d.model,d.package_key,d.package_name,d.catalogue_category,d.main_category,d.product_type,d.notes,d.active,d.customer_visible from data d join public.catalogue_master_categories c on c.slug=d.category_slug left join public.catalogue_master_branches b on b.category_id=c.id and b.slug=d.branch_slug join public.catalogue_master_manufacturers m on m.name=d.manufacturer_name
on conflict (category_id,branch_id,manufacturer_id,model,package_key) do update set package_name=excluded.package_name,catalogue_category=excluded.catalogue_category,main_category=excluded.main_category,product_type=excluded.product_type,notes=excluded.notes,active=excluded.active,customer_visible=excluded.customer_visible;
